body:
Given the imminent release of 4.7, I took a bit of a shortcut and asked Claude to attempt a regression fix. It's not my area of expertise so I'm reluctant to propose it as an actual fix, but I'll share the findings in case it can be useful to @Ivorforce or @Faless to decide what is the proper fix.

The diff is verbose (AI style...) but it's mostly from the test case added to reproduce the MRP's bug and confirm it's fixed. The actual changes to PacketPeerMbedDTLS are fairly minimal.

```diff
diff --git a/modules/mbedtls/packet_peer_mbed_dtls.cpp b/modules/mbedtls/packet_peer_mbed_dtls.cpp
index 3316ac8593..af019ebf58 100644
--- a/modules/mbedtls/packet_peer_mbed_dtls.cpp
+++ b/modules/mbedtls/packet_peer_mbed_dtls.cpp
@@ -95,11 +95,20 @@ int PacketPeerMbedDTLS::_set_cookie() {
 Error PacketPeerMbedDTLS::_do_handshake() {
 	int ret = 0;
 	while ((ret = mbedtls_ssl_handshake(tls_ctx->get_context())) != 0) {
+		if (ret == MBEDTLS_ERR_SSL_HELLO_VERIFY_REQUIRED) {
+			// DTLS server cookie exchange: mbedTLS has sent a HelloVerifyRequest and
+			// expects the client to retransmit its ClientHello with the cookie. Reset
+			// the session (which clears the client transport ID) and re-arm the cookie,
+			// then keep handshaking. The peer and its incoming packet queue are kept
+			// alive by the DTLSServer, so the retransmitted ClientHello is delivered
+			// back to this same peer and processed on the next poll.
+			mbedtls_ssl_session_reset(tls_ctx->get_context());
+			_set_cookie();
+			return OK;
+		}
 		if (ret != MBEDTLS_ERR_SSL_WANT_READ && ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
-			if (ret != MBEDTLS_ERR_SSL_HELLO_VERIFY_REQUIRED) {
-				ERR_PRINT("TLS handshake error: " + itos(ret));
-				TLSContextMbedTLS::print_mbedtls_error(ret);
-			}
+			ERR_PRINT("TLS handshake error: " + itos(ret));
+			TLSContextMbedTLS::print_mbedtls_error(ret);
 			_cleanup();
 			status = STATUS_ERROR;
 			return FAILED;
diff --git a/modules/mbedtls/tests/test_crypto_mbedtls.cpp b/modules/mbedtls/tests/test_crypto_mbedtls.cpp
index beb8d9d65d..c1105fca10 100644
--- a/modules/mbedtls/tests/test_crypto_mbedtls.cpp
+++ b/modules/mbedtls/tests/test_crypto_mbedtls.cpp
@@ -32,7 +32,12 @@

 #include "../crypto_mbedtls.h"

+#include "core/io/dtls_server.h"
 #include "core/io/file_access.h"
+#include "core/io/packet_peer_dtls.h"
+#include "core/io/packet_peer_udp.h"
+#include "core/io/udp_server.h"
+#include "core/os/os.h"
 #include "tests/test_macros.h"
 #include "tests/test_utils.h"

@@ -100,4 +105,77 @@ void crypto_key_save_public_only_test(const String &p_in_priv_path, const String
 	bool is_equal = files_equal(p_in_pub_path, p_out_path);
 	CHECK(is_equal);
 }
+
+void dtls_handshake_test() {
+	const int PORT = 44443;
+	const IPAddress LOCALHOST("127.0.0.1");
+
+	// Generate a self-signed certificate / key pair for the server.
+	Ref<Crypto> crypto = Ref<Crypto>(Crypto::create());
+	REQUIRE(crypto.is_valid());
+	Ref<CryptoKey> key = crypto->generate_rsa(2048);
+	REQUIRE(key.is_valid());
+	Ref<X509Certificate> cert = crypto->generate_self_signed_certificate(key, "CN=godot.test,O=Godot,C=US", "20140101000000", "20340101000000");
+	REQUIRE(cert.is_valid());
+
+	// Server side: UDP server + DTLS server.
+	Ref<UDPServer> udp_server;
+	udp_server.instantiate();
+	REQUIRE_EQ(udp_server->listen(PORT, LOCALHOST), OK);
+
+	Ref<DTLSServer> dtls_server = Ref<DTLSServer>(DTLSServer::create());
+	REQUIRE(dtls_server.is_valid());
+	REQUIRE_EQ(dtls_server->setup(TLSOptions::server(key, cert)), OK);
+
+	// Client side: connected UDP peer + DTLS peer.
+	Ref<PacketPeerUDP> client_udp;
+	client_udp.instantiate();
+	REQUIRE_EQ(client_udp->connect_to_host(LOCALHOST, PORT), OK);
+
+	Ref<PacketPeerDTLS> client_dtls = Ref<PacketPeerDTLS>(PacketPeerDTLS::create());
+	REQUIRE(client_dtls.is_valid());
+	// Trust our own self-signed cert directly so the test does not depend on the
+	// default certificate bundle being loaded in the headless test runner.
+	REQUIRE_EQ(client_dtls->connect_to_peer(client_udp, "godot.test", TLSOptions::client(cert, "godot.test")), OK);
+
+	Ref<PacketPeerDTLS> server_peer;
+
+	// Pump both ends until the DTLS handshake (including the DTLS cookie exchange)
+	// completes, or until we run out of time. Regression test for GH-120291: the
+	// cookie exchange must be carried out in place on the same peer.
+	const uint64_t deadline = OS::get_singleton()->get_ticks_msec() + 5000;
+	while (OS::get_singleton()->get_ticks_msec() < deadline) {
+		client_dtls->poll();
+		udp_server->poll();
+
+		if (server_peer.is_null() && udp_server->is_connection_available()) {
+			Ref<PacketPeerUDP> conn = udp_server->take_connection();
+			REQUIRE(conn.is_valid());
+			server_peer = dtls_server->take_connection(conn);
+			REQUIRE(server_peer.is_valid());
+		}
+		if (server_peer.is_valid()) {
+			server_peer->poll();
+		}
+
+		const PacketPeerDTLS::Status cs = client_dtls->get_status();
+		const PacketPeerDTLS::Status ss = server_peer.is_valid() ? server_peer->get_status() : PacketPeerDTLS::STATUS_HANDSHAKING;
+		if (cs == PacketPeerDTLS::STATUS_ERROR || ss == PacketPeerDTLS::STATUS_ERROR) {
+			break; // Handshake failed; assertions below will report it.
+		}
+		if (cs == PacketPeerDTLS::STATUS_CONNECTED && ss == PacketPeerDTLS::STATUS_CONNECTED) {
+			break;
+		}
+		OS::get_singleton()->delay_usec(1000);
+	}
+
+	// Both ends should end up connected. On the GH-120291 regression the server peer
+	// is stuck in STATUS_ERROR and the client never leaves STATUS_HANDSHAKING.
+	CHECK_EQ(client_dtls->get_status(), PacketPeerDTLS::STATUS_CONNECTED);
+	REQUIRE(server_peer.is_valid());
+	CHECK_EQ(server_peer->get_status(), PacketPeerDTLS::STATUS_CONNECTED);
+
+	client_dtls->disconnect_from_peer();
+	udp_server->stop();
+}
 } // namespace TestCryptoMbedTLS
diff --git a/modules/mbedtls/tests/test_crypto_mbedtls.h b/modules/mbedtls/tests/test_crypto_mbedtls.h
index ec0acefc23..2f88648f41 100644
--- a/modules/mbedtls/tests/test_crypto_mbedtls.h
+++ b/modules/mbedtls/tests/test_crypto_mbedtls.h
@@ -84,4 +84,10 @@ TEST_CASE("[Crypto] CryptoKey save public_only") {
 	crypto_key_save_public_only_test(in_priv_path, in_pub_path, out_path);
 }

+void dtls_handshake_test();
+
+TEST_CASE("[DTLS] Server/client handshake loopback") {
+	dtls_handshake_test();
+}
+
 } // namespace TestCryptoMbedTLS
diff --git a/modules/mbedtls/tls_context_mbedtls.cpp b/modules/mbedtls/tls_context_mbedtls.cpp
index 9c791c50d4..2c492acd8c 100644
--- a/modules/mbedtls/tls_context_mbedtls.cpp
+++ b/modules/mbedtls/tls_context_mbedtls.cpp
@@ -79,6 +79,7 @@ void CookieContextMbedTLS::clear() {
 	mbedtls_ctr_drbg_free(&ctr_drbg);
 	mbedtls_entropy_free(&entropy);
 	mbedtls_ssl_cookie_free(&cookie_ctx);
+	inited = false;
 }

 CookieContextMbedTLS::CookieContextMbedTLS() {
```

It's not clear how this relates to the PR which was identified as causing the regression. It might be that the bug pre-existed and was just made worse by ownership/timing changes (maybe specifically for how this MRP handles the connection).

I note that with the MRP, the "good" behavior in 4.6.3 does seem partially bad too (requires 2 handshakes to connect successfully, double frees a mutex on exit).
